package com.grantora.service;
import com.grantora.entity.*; import com.grantora.repository.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@Service
public class WorkflowAutomationService {
 private final WorkflowDeadlineConfigRepository configs; private final GrantApplicationRepository apps; private final WorkflowEscalationRepository escalations; private final InAppNotificationRepository notifications; private final UserRepository users;
 public WorkflowAutomationService(WorkflowDeadlineConfigRepository c,GrantApplicationRepository a,WorkflowEscalationRepository e,InAppNotificationRepository n,UserRepository u){configs=c;apps=a;escalations=e;notifications=n;users=u;}
 public WorkflowDeadlineConfig config(){return configs.findById(1L).orElseGet(()->configs.save(new WorkflowDeadlineConfig()));}
 @Transactional public WorkflowDeadlineConfig update(WorkflowDeadlineConfig req){if(req.getFieldDays()<1||req.getFieldDays()>365||req.getDistrictDays()<1||req.getDistrictDays()>365||req.getStateDays()<1||req.getStateDays()>365||req.getScanMinutes()<1||req.getScanMinutes()>1440)throw new IllegalArgumentException("Deadlines must be 1–365 days and scan interval 1–1440 minutes."); WorkflowDeadlineConfig c=config(); c.setFieldDays(req.getFieldDays());c.setDistrictDays(req.getDistrictDays());c.setStateDays(req.getStateDays());c.setScanMinutes(req.getScanMinutes());c.touch();return configs.save(c);}
 @Scheduled(fixedDelayString="${grantora.workflow.scan-ms:60000}") @Transactional public void detectOverdue(){LocalDateTime now=LocalDateTime.now();for(GrantApplication a:apps.findAllByOrderByIdDesc()){if(a.getWorkflowStage()==null||a.getAssignedOfficer()==null||a.getTaskDueAt()==null||a.getTaskDueAt().isAfter(now)||a.getTaskCompletedAt()!=null||a.getStatus()==GrantApplicationStatus.APPROVED||a.getStatus()==GrantApplicationStatus.REJECTED||escalations.existsByApplication_IdAndStageAndResolvedFalse(a.getId(),a.getWorkflowStage()))continue; WorkflowEscalation e=new WorkflowEscalation();e.setApplication(a);e.setStage(a.getWorkflowStage());e.setAssignedOfficer(a.getAssignedOfficer());e.setReason("Workflow task exceeded its configured deadline.");escalations.save(e);a.setEscalated(true);for(User u:users.findAll())if(u.getRole()==Role.ADMIN)notify(u,"overdue:"+a.getId()+":"+a.getWorkflowStage(),"Application #"+a.getId()+" is overdue at "+a.getWorkflowStage()+".",a.getId());}}
 @Transactional public void notify(User user,String key,String message,Long app){if(user==null||notifications.existsByUser_IdAndEventKey(user.getId(),key))return;InAppNotification n=new InAppNotification();n.setUser(user);n.setEventKey(key);n.setMessage(message);n.setApplicationId(app);notifications.save(n);}
 public List<WorkflowEscalation> escalations(String email,boolean admin){if(admin)return escalations.findAllByOrderByCreatedAtDesc();User u=users.findByEmail(email).orElseThrow();if(u.getRole()!=Role.OFFICER)throw new org.springframework.security.access.AccessDeniedException("Officer access required");return escalations.findAllByOrderByCreatedAtDesc().stream().filter(e->e.getAssignedOfficer()!=null&&Objects.equals(e.getAssignedOfficer().getId(),u.getId())).toList();}
 @Transactional public WorkflowEscalation resolve(Long id,String email){User actor=users.findByEmail(email).orElseThrow();if(actor.getRole()!=Role.ADMIN)throw new org.springframework.security.access.AccessDeniedException("Admin access required");WorkflowEscalation e=escalations.findByIdAndResolvedFalse(id).orElseThrow();e.resolve(actor,"Reviewed by Admin");return e;}
 public List<InAppNotification> notifications(String email){User u=users.findByEmail(email).orElseThrow();return notifications.findByUser_IdOrderByCreatedAtDesc(u.getId());}
 public long unread(String email){User u=users.findByEmail(email).orElseThrow();return notifications.countByUser_IdAndReadAtIsNull(u.getId());}
 @Transactional public void markRead(Long id,String email){User u=users.findByEmail(email).orElseThrow();InAppNotification n=notifications.findByIdAndUser_Id(id,u.getId()).orElseThrow();n.markRead();}
}
